  "facts": [
    {
      "key": "brief-order",
      "path": "architecture.cli.brief",
      "kind": "decision",
      "text": "The brief command emits facts and history before the status block so agents that truncate long packets still see the evidence first."
    },
    {
      "key": "brief-status-size",
      "path": "architecture.cli.brief",
      "kind": "gotcha",
      "text": "A brief status block that grows past about ten kilobytes crowds out evidence; keep status after facts and history and trim it to counts."
    },
    {
      "key": "brief-recall-name",
      "path": "architecture.cli.brief",
      "kind": "convention",
      "text": "Agent guides name recall, not query, as the command for prior decisions because query ranks docs and facts together."
    },
    {
      "key": "query-expansion-optin",
      "path": "project.evaluation.retrieval",
      "kind": "decision",
      "text": "Query expansion stays opt-in: an early effect of d 0.47 at n 8 collapsed to d 0.10 with p 0.26 at n 121."
    },
    {
      "key": "bm25-default",
      "path": "architecture.retrieval.ranking",
      "kind": "decision",
      "text": "BM25 over tokenized history replaced substring matching as the default ranker after a 2.7x to 5.1x useful-per-1k gain across strata."
    },
    {
      "key": "model2vec-rejected",
      "path": "project.evaluation.retrieval",
      "kind": "decision",
      "text": "Model2Vec fusion on history was dropped: precision was significantly worse than BM25 at production scale and the small-repo gain was noise."
    },
    {
      "key": "rrf-weights",
      "path": "architecture.retrieval.ranking",
      "kind": "decision",
      "text": "Reciprocal rank fusion keeps equal weights and k0 of 60; a weight sweep put every cell inside noise."
    },
    {
      "key": "locus-scoped",
